import http.server
import json

import requests

DATABASE = 'postgres://shop:hunter2@db/shop'


def rates():
    return requests.get('https://rates.example.com/latest').json()


class Handler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        body = json.dumps(rates()).encode()
        self.send_response(200)
        self.end_headers()
        self.wfile.write(body)


http.server.HTTPServer(('', 8000), Handler).serve_forever()
